import * as React from 'react';
import { cn } from '@/lib/utils';

export type ProcessStep = {
  title: string;
  description?: string;
  icon?: React.ReactNode;
};

export type ProcessStepsProps = React.HTMLAttributes<HTMLOListElement> & {
  /** Ordered steps. */
  steps: ProcessStep[];
  /** Desktop column count (2-4). Default 3. */
  columns?: 2 | 3 | 4;
  /** Show step numbers when no icon is provided. Default true. */
  numbered?: boolean;
  /** Content alignment. Default 'left'. */
  align?: 'left' | 'center';
};

const columnClasses: Record<NonNullable<ProcessStepsProps['columns']>, string> = {
  2: 'sm:grid-cols-2',
  3: 'sm:grid-cols-2 lg:grid-cols-3',
  4: 'sm:grid-cols-2 lg:grid-cols-4',
};

/**
 * Ordered process or onboarding steps. Numbers are derived from the list
 * order and announced as an ordered list, so the sequence survives without
 * relying on decorative connectors.
 */
export const ProcessSteps = React.forwardRef<HTMLOListElement, ProcessStepsProps>(function ProcessSteps(
  { steps, columns = 3, numbered = true, align = 'left', className, ...props },
  ref
) {
  return (
    <ol ref={ref} className={cn('grid gap-8', columnClasses[columns], className)} {...props}>
      {steps.map((step, index) => (
        <li
          key={step.title}
          className={cn('flex min-w-0 flex-col gap-4', align === 'center' && 'items-center text-center')}
        >
          <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary/10 text-sm font-semibold text-primary [&_svg]:size-5">
            {step.icon ?? (numbered ? String(index + 1).padStart(2, '0') : null)}
          </span>
          <div className="min-w-0">
            <h3 className="text-base font-semibold tracking-tight">{step.title}</h3>
            {step.description && (
              <p className="mt-1 text-sm leading-relaxed text-muted-foreground">{step.description}</p>
            )}
          </div>
        </li>
      ))}
    </ol>
  );
});

{
  "id": "process-steps",
  "name": "ProcessSteps",
  "tier": "organism",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.5.0",
  "sourceDir": "process-steps",
  "exportName": "ProcessSteps",
  "description": "Ordered process cards with derived step numbers or custom icons.",
  "designIntent": "Marketing pages explain a process as 01/02/03 cards. ProcessSteps uses an ordered list so the sequence is structural, derives the numbers from order and supports icons without turning the section into arbitrary divs.",
  "props": [
    {
      "name": "steps",
      "type": "ProcessStep[]",
      "required": true,
      "description": "Ordered steps: title, optional description and icon."
    },
    {
      "name": "columns",
      "type": "2 | 3 | 4",
      "required": false,
      "defaultValue": "3",
      "description": "Desktop column count."
    },
    {
      "name": "numbered",
      "type": "boolean",
      "required": false,
      "defaultValue": "true",
      "description": "Show step numbers when no icon is provided."
    },
    {
      "name": "align",
      "type": "'left' | 'center'",
      "required": false,
      "defaultValue": "left",
      "enum": [
        "left",
        "center"
      ],
      "description": "Content alignment."
    }
  ],
  "examples": [
    {
      "title": "Advisor process",
      "code": "<ProcessSteps\n  steps={[\n    { title: 'Meet your consultant', description: 'Share your goals.' },\n    { title: 'Review advisors', description: 'Compare recommendations.' },\n    { title: 'Interview and hire', description: 'Choose with confidence.' },\n  ]}\n/>",
      "description": "Three numbered process steps."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't hardcode step numbers",
      "explanation": "Numbers come from the list order. Hardcoded numbers drift when steps are inserted or reordered.",
      "example": "// Avoid\nsteps={[{ title: '01. Meet' }]}"
    }
  ],
  "accessibility": [
    {
      "feature": "Ordered sequence",
      "implementation": "Renders ol/li so the order is announced",
      "userRequirements": "Keep steps in the intended order"
    },
    {
      "feature": "Icon or number",
      "implementation": "The marker is visual; the list order carries the sequence",
      "userRequirements": "Provide a title for every step"
    }
  ],
  "compositionRules": [
    {
      "component": "Section",
      "relationship": "Place ProcessSteps inside a Section band",
      "example": "<Section><ProcessSteps steps={steps} /></Section>"
    }
  ],
  "relatedComponents": [
    "Stepper",
    "Timeline",
    "FeatureGrid"
  ]
}
